namespace Civi\Lughauth\Features\Document\Snippet\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Create\SnippetCreateUsecase;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetUidVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetCodeVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Create\SnippetCreateParams;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Create\SnippetCreateResult;

class SnippetCreateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly SnippetCreateUsecase $createUsecase,
    ) {
    }
    #[OA\Post(
        path: "/api/document/snippet",
        tags: ["Snippet"],
        description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetApiDTO")),
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetApiDTO")),
              new OA\Response(response: 422, description: "Constraint error"),
          ]
    )]
    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Create Snippet");
        $span = $this->startSpan("Create Snippet");
        $this->sql->begin();
        try {
            $value = $this->readSnippet($request);
            $result = $this->createUsecase->create($value);
            $this->sql->commit();
            $value = $this->mapSnippet($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readSnippet(ServerRequestInterface $request): SnippetCreateParams
    {
        $this->logDebug("Read entity for Snippet");
        $span = $this->startSpan("Read entity for Snippet");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new SnippetCreateParams();
            $valueUid = SnippetUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            $valueCode = SnippetCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            if (in_array('tenant', array_keys($body))) {
                $value->tenant(SnippetTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList));
            }
            $value->version(SnippetVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapSnippet(ServerRequestInterface $request, SnippetCreateResult $value): SnippetApiDTO
    {
        $this->logDebug("Map entity to output dto for Snippet");
        $span = $this->startSpan("Map entity to output dto for Snippet");
        try {
            $tenant = $value->getTenant();
            $dto = new SnippetApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
